(function () {
const html = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>Retirement Planning</title>\n  <!-- Load DM Sans and DM Mono fonts -->\n  <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n  <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n  <link href=\"https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300&family=DM+Sans:ital,opsz,wght@0,9..40,100..1000;1,9..40,100..1000&display=swap\" rel=\"stylesheet\">\n  <script id=\"MathJax-script\" async src=\"https://cdn.jsdelivr.net/npm/mathjax@3/dist/solid.js\"></script>\n  <script src=\"https://cdn.jsdelivr.net/npm/mathjax@3/dist/browser.js\"></script>\n  <script>\n    window.MathJax = {\n      tex: {\n        inlineMath: [['$', '$'], ['\\\\(', '\\\\)']],\n        displayMath: [['$$', '$$'], ['\\\\[', '\\\\]']]\n      }\n    };\n  </script>\n\n  <style>\n    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }\n    :root {\n      --bg: #f7f6f2; --surface: #fff; --surface2: #f2f0eb;\n      --border: #e2dfd8; --border-strong: #c8c4bb;\n      --text: #1a1916; --text2: #6b6860; --text3: #a09d98;\n      --green: #1a6b47; --green-bg: #edf7f2;\n      --blue: #1a4a6b; --blue-bg: #edf3f7;\n      --red: #6b1a1a; --red-bg: #f7eded;\n      --gold: #6b4e1a; --gold-bg: #f7f2ed;\n      --orange: #b85c00; --amber: #c97a1a;\n      --r: 6px; --rl: 10px;\n      --shadow: 0 1px 3px rgba(0,0,0,0.06);\n    }\n    body { font-family:'DM Sans',sans-serif; background:var(--bg); color:var(--text); font-size:14px; line-height:1.5; min-height:100vh; }\n\n    /* \u2500\u2500 TOPBAR \u2500\u2500 */\n    .topbar { background:var(--surface); border-bottom:1px solid var(--border); padding:0 1.5rem; display:flex; align-items:center; justify-content:space-between; height:56px; position:sticky; top:0; z-index:200; }\n    .brand { display:flex; align-items:center; gap:10px; }\n    .brand-mark { width:28px; height:28px; background:var(--text); border-radius:6px; display:flex; align-items:center; justify-content:center; flex-shrink:0; }\n    .brand-mark svg { width:14px; height:14px; fill: #fff; }\n    .brand-name { font-size:14px; font-weight:500; letter-spacing:-0.01em; }\n    .brand-sub { font-size:12px; color:var(--text3); margin-left:2px; }\n    .pill-nav { display:flex; background:var(--surface2); border-radius:20px; padding:3px; gap:2px; }\n    .pill-btn { padding:5px 16px; border-radius:16px; border:none; background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; font-weight:400; transition:all .15s; }\n    .pill-btn.active { background:var(--surface); color:var(--text); font-weight:500; box-shadow:0 1px 2px rgba(0,0,0,.08); }\n\n    /* \u2500\u2500 PAGE SHELLS \u2500\u2500 */\n    .page { display:none; }\n    .page.active { display:flex; min-height:calc(100vh - 56px); }\n\n    /* \u2500\u2500 ENTRY LAYOUT \u2500\u2500 */\n    .sidebar { width:260px; flex-shrink:0; background:var(--surface); border-right:1px solid var(--border); position:sticky; top:56px; height:calc(100vh - 56px); overflow-y:auto; padding:1.25rem 0; }\n    .main-area { flex:1; padding:2rem; overflow-y:auto; min-width:0; }\n\n    /* sidebar nav */\n    .sb-label { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); padding:0 1.25rem; margin-bottom:.5rem; }\n    .sb-item { display:flex; align-items:center; gap:10px; padding:9px 1.25rem; cursor:pointer; border-left:2px solid transparent; transition:all .12s; font-size:13px; color:var(--text2); text-decoration:none; }\n    .sb-item:hover { background:var(--surface2); color:var(--text); }\n    .sb-item.active { border-left-color:var(--text); color:var(--text); font-weight:500; background:var(--surface2); }\n    .sb-dot { width:6px; height:6px; border-radius:50%; flex-shrink:0; }\n    .d1 { background:var(--green); } .d2 { background:var(--blue); } .d3 { background:var(--gold); } .d4 { background:var(--text3); }\n\n    /* progress */\n    .prog-wrap { padding:1.25rem 1.25rem .75rem; }\n    .prog-top { display:flex; justify-content:space-between; font-size:11px; color:var(--text3); margin-bottom:6px; }\n    .prog-track { height:3px; background:var(--surface2); border-radius:2px; overflow:hidden; }\n    .prog-fill { height:100%; background:var(--text); border-radius:2px; width:0%; transition:width .4s; }\n\n    /* per-segment sidebar summaries */\n    .seg-sum { display:none; margin:0 1rem .75rem; }\n    .seg-sum.on { display:block; }\n    .ss-head { color:#fff; font-size:10px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; padding:6px 10px; border-radius:var(--r) var(--r) 0 0; }\n    .ss-body { background:var(--surface2); border-radius:0 0 var(--r) var(--r); padding:8px 10px; border:1px solid var(--border); border-top:none; }\n    .ss-row { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; color:var(--text2); border-bottom:1px solid var(--border); }\n    .ss-row:last-child { border-bottom:none; }\n    .ss-row.neg { color:var(--red); }\n    .ss-v { font-family:'DM Mono',monospace; font-size:11px; color:var(--text); }\n    .ss-b { font-weight:500; }\n    .ss-div { height:1px; background:var(--border-strong); margin:5px 0; }\n    .ss-tot { display:flex; justify-content:space-between; align-items:baseline; padding:3px 0; font-size:11px; font-weight:500; }\n    .positive { color:var(--green); } .negative { color:var(--red); } .neutral { color:var(--blue); } .warning { color:var(--amber); }\n\n    /* \u2500\u2500 SEGMENT CONTENT \u2500\u2500 */\n    .segment { display:none; }\n    .segment.active { display:block; }\n    .seg-hdr { display:flex; align-items:flex-start; justify-content:space-between; margin-bottom:1.75rem; }\n    .seg-tag { display:inline-flex; align-items:center; padding:3px 10px; border-radius:20px; font-size:11px; font-weight:500; margin-bottom:6px; }\n    .t1{background:var(--green-bg);color:var(--green);} .t2{background:var(--blue-bg);color:var(--blue);} .t3{background:var(--gold-bg);color:var(--gold);} .t4{background:var(--surface2);color:var(--text2);}\n    .seg-title { font-size:22px; font-weight:300; letter-spacing:-.03em; }\n    .seg-desc { font-size:13px; color:var(--text3); margin-top:4px; }\n    .seg-tot-box { text-align:right; background:var(--surface2); border-radius:var(--rl); padding:10px 16px; }\n    .tot-label { font-size:11px; color:var(--text3); }\n    .tot-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n\n    /* cards */\n    .card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); margin-bottom:1rem; overflow:hidden; box-shadow:var(--shadow); }\n    .ch { display:flex; align-items:center; justify-content:space-between; padding:12px 16px; cursor:pointer; user-select:none; border-bottom:1px solid transparent; transition:background .12s; }\n    .ch:hover { background:var(--surface2); }\n    .ch.open { border-bottom-color:var(--border); }\n    .ch-left { display:flex; align-items:center; gap:10px; }\n    .ci { width:28px; height:28px; border-radius:6px; display:flex; align-items:center; justify-content:center; font-size:13px; flex-shrink:0; }\n    .ci1{background:var(--green-bg); color:var(--green);} .ci2{background:var(--blue-bg); color:var(--blue);} .ci3{background:var(--gold-bg); color:var(--gold);} .ci-r{background:var(--red-bg); color:var(--red);} .ci-g{background:var(--surface2); color:var(--text2);}\n    .ch-title { font-size:13px; font-weight:500; }\n    .ch-sub { font-size:11px; color:var(--text3); margin-top:1px; }\n    .ch-right { display:flex; align-items:center; gap:10px; }\n    .ch-sum { font-family:'DM Mono',monospace; font-size:13px; color:var(--text2); }\n    .chev { width:16px; height:16px; color:var(--text3); transition:transform .2s; flex-shrink:0; }\n    .chev.open { transform:rotate(180deg); }\n    .cb { display:none; padding:14px 16px; }\n    .cb.open { display:block; }\n\n    /* fields */\n    .f-static { display:grid; grid-template-columns:260px 1fr ; gap:12px; align-items:center; padding:10px 0; border-bottom:1px solid var(--border); }\n    .f-static:last-of-type { border-bottom:none; }\n    .f-label { font-size:13px; }\n    .f-sub { font-size:11px; color:var(--text3); margin-top: 2px; }\n    .pfx-wrap { position:relative; }\n    .pfx { position:absolute; left:10px; top:50%; transform:translateY(-50%); font-size:12px; color:var(--text3); pointer-events:none; }\n    .inp { width:100%; height:34px; border:1px solid var(--border); border-radius:var(--r); padding:0 10px; font-size:13px; font-family:'DM Mono',monospace; color:var(--text); background:var(--surface); text-align:right; transition:border-color .12s; }\n    .inp:focus { outline:none; border-color:var(--text); }\n    .inp.pl { padding-left:26px; text-align:left; }\n    .inp-t { height:34px; border:1px solid var(--border); border-radius:var(--r); padding:0 10px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface); width:100%; transition:border-color .12s; }\n    .inp-t:focus { outline:none; border-color:var(--text); }\n    .exp-rows { margin-top:10px; }\n    .exp-row { display:grid; grid-template-columns:1fr 160px 30px; gap:6px; align-items:center; margin-bottom:6px; animation:fi .15s ease; }\n    .exp-row-4 { display:grid; grid-template-columns:130px 1fr 150px 30px; gap:6px; align-items:center; margin-bottom:6px; animation:fi .15s ease; }\n    @keyframes fi { from{opacity:0;transform:translateY(-4px)} to{opacity:1;transform:translateY(0)} }\n    .btn-rm { width:28px; height:28px; border:1px solid var(--border); border-radius:var(--r); background:transparent; cursor:pointer; color:var(--text3); display:flex; align-items:center; justify-content:center; font-size:16px; transition:all .12s; }\n    .btn-rm:hover { border-color:var(--red); color:var(--red); background:var(--red-bg); }\n    .btn-add { display:flex; align-items:center; gap:6px; padding:6px 10px; border:1px dashed var(--border-strong); border-radius:var(--r); background:transparent; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; margin-top:4px; width:100%; transition:all .12s; }\n    .btn-add:hover { border-color:var(--text); color:var(--text2); background:var(--surface2); }\n    .ded-section { margin-top:1.5rem; padding-top:1.25rem; border-top:1px dashed var(--border); }\n    .ded-lbl { font-size:11px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; color:var(--red); margin-bottom:.75rem; }\n    .age-input{text-align:left;}\n\n    /* nav buttons */\n    .seg-nav { display:flex; justify-content:space-between; align-items:center; margin-top:2rem; padding-top:1.5rem; border-top:1px solid var(--border); }\n    .btn-nav { display:flex; align-items:center; gap:6px; padding:9px 18px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text2); cursor:pointer; transition:all .12s; }\n    .btn-nav:hover { border-color:var(--text); color:var(--text); }\n    .btn-pri { background:var(--text); color:#fff; border-color:var(--text); }\n    .btn-pri:hover { background:#333; }\n\n    /* \u2500\u2500 ANALYSIS PAGE \u2500\u2500 */\n    #page-analysis .main-area { max-width:1100px; margin:0 auto; }\n    .a-header { margin-bottom:1.75rem; }\n    .a-title { font-size:28px; font-weight:300; letter-spacing:-.03em; }\n    .a-sub { font-size:13px; color:var(--text3); margin-top:4px; }\n    .sec-title { font-size:10px; font-weight:500; letter-spacing:.08em; text-transform:uppercase; color:var(--text3); margin-bottom:.75rem; margin-top:1.5rem; }\n\n    /* quadrant */\n    .quad-grid { display:grid; grid-template-columns:repeat(2, minmax(0,1fr)); gap:10px; margin-bottom:1rem; }\n    .quad-card { border-radius:var(--rl); overflow:hidden; border:1px solid var(--border); cursor:pointer; transition:transform .15s, box-shadow .15s; }\n    .quad-card:hover { transform:translateY(-2px); box-shadow:0 6px 20px rgba(0,0,0,.1); }\n    .quad-card:active { transform:translateY(0); box-shadow:none; }\n    .q-hint { font-size:10px; color:rgba(255,255,255,.7); font-style:italic; float:right; font-weight:400; letter-spacing:0; }\n    .q-head { padding:8px 12px; font-size:11px; font-weight:500; letter-spacing:.05em; text-transform:uppercase; color:#fff; }\n    .qg{background:#1a6b47;} .qr{background:#8b2020;} .qb{background:#1a4a6b;} .qo{background:#b85c00;}\n    .q-body { background:var(--surface); padding:10px 12px; }\n    .q-row { display:flex; justify-content:space-between; padding:4px 0; font-size:12px; color:var(--text2); border-bottom:1px solid var(--surface2); }\n    .q-row:last-child { border-bottom:none; }\n    .q-val { font-family:'DM Mono',monospace; font-size:12px; font-weight:500; color:var(--text); }\n    .q-div { height:1px; background:var(--border); margin:6px 0; }\n    .q-foot { display:flex; justify-content:space-between; padding:4px 0 0; font-size:12px; font-weight:500; }\n    .q-fv { font-family:'DM Mono',monospace; font-size:13px; font-weight:500; }\n\n    /* matrix */\n    .mx-grid { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .mx-item { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .mx-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:3px; }\n    .mx-fml { font-size:10px; color:var(--text3); opacity:.7; margin-bottom:8px; font-style:italic; }\n    .mx-val { font-size:22px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .mx-sub { font-size:11px; color:var(--text3); margin-top:3px; }\n\n    /* kpi strip */\n    .kpi-grid { display:grid; grid-template-columns:repeat(4, minmax(0,1fr)); gap:10px; margin-bottom:1.5rem; }\n    .kpi { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .kpi-lbl { font-size:11px; color:var(--text3); letter-spacing:.03em; margin-bottom:6px; }\n    .kpi-val { font-size:20px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .kpi-sub { font-size:11px; color:var(--text3); margin-top:4px; }\n\n    /* analysis cards */\n    .a-card { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1.25rem; margin-bottom:1rem; }\n    .a-card-title { font-size:13px; font-weight:500; margin-bottom:1rem; display:flex; align-items:center; gap:8px; }\n    .a-dot { width:8px; height:8px; border-radius:50%; flex-shrink:0; }\n    .two-col { display:grid; grid-template-columns:1fr 1fr; gap:1rem; margin-bottom:1rem; }\n    .chart-wrap { position:relative; }\n    .bar-list { display:flex; flex-direction:column; gap:10px; }\n    .bar-item-top { display:flex; justify-content:space-between; margin-bottom:5px; font-size:12px; }\n    .bar-lbl { color:var(--text2); }\n    .bar-val { font-family:'DM Mono',monospace; font-weight:500; }\n    .bar-track { height:6px; background:var(--surface2); border-radius:4px; overflow:hidden; }\n    .bar-fill { height:100%; border-radius:4px; transition:width .8s; }\n    .bk-table { width:100%; border-collapse:collapse; }\n    .bk-table th { font-size:11px; font-weight:500; color:var(--text3); text-align:left; padding:0 0 8px; border-bottom:1px solid var(--border); }\n    .bk-table th:last-child { text-align:right; }\n    .bk-table td { padding:8px 0; font-size:13px; border-bottom:1px solid var(--surface2); vertical-align:middle; }\n    .bk-table td:last-child { text-align:right; font-family:'DM Mono',monospace; font-weight:500; }\n    .bk-table tr:last-child td { border-bottom:none; }\n    .cat-badge { display:inline-flex; align-items:center; gap:5px; }\n    .cat-dot { width:6px; height:6px; border-radius:50%; }\n    .ratio-item { display:flex; align-items:center; gap:8px; margin-bottom:8px; }\n    .ratio-lbl { font-size:12px; color:var(--text2); width:130px; flex-shrink:0; }\n    .ratio-track { flex:1; background:var(--surface2); height:8px; border-radius:4px; overflow:hidden; }\n    .ratio-fill { height:100%; border-radius:4px; }\n    .ratio-pct { font-size:12px; font-family:'DM Mono',monospace; width:42px; text-align:right; }\n    .health-grid { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; }\n    .h-item { background:var(--surface2); border-radius:var(--r); padding:10px 12px; }\n    .h-score { font-size:18px; font-weight:500; font-family:'DM Mono',monospace; margin-bottom:2px; }\n    .h-lbl { font-size:11px; color:var(--text3); }\n    .h-tag { font-size:10px; font-weight:500; padding:2px 8px; border-radius:10px; margin-top:6px; display:inline-block; }\n    .tg{background:var(--green-bg);color:var(--green);} .tw{background:#fff8e8;color:var(--amber);} .tb{background:var(--red-bg);color:var(--red);}\n    .nw-val { font-size:32px; font-weight:300; font-family:'DM Mono',monospace; letter-spacing:-.04em; }\n\n    .empty-state { text-align:center; padding:4rem 1rem; color:var(--text3); }\n    .empty-state a { color:var(--blue); text-decoration:none; font-weight:500; cursor:pointer; }\n\n    /* net worth duo */\n    .nw-duo-grid { display:grid; grid-template-columns:1fr 1fr; gap:10px; margin-bottom:.5rem; }\n    .nw-card { background:var(--surface2); border:1px solid var(--border); border-radius:var(--rl); padding:1rem 1.25rem; }\n    .nw-card-lbl { font-size:12px; font-weight:500; color:var(--text2); margin-bottom:3px; display:flex; align-items:center; gap:6px; }\n    .nw-card-fml { font-size:11px; color:var(--text3); font-style:italic; margin-bottom:10px; }\n    .nw-card-val { font-size:24px; font-weight:500; font-family:'DM Mono',monospace; letter-spacing:-.03em; }\n    .nw-epf-tag { font-size:10px; font-weight:500; padding:2px 7px; border-radius:10px; }\n    .with-epf { background:#e8f5ee; color:#1a6b47; }\n    .no-epf   { background:#f5ede8; color:#8b3a1a; }\n\n    /* group blocks */\n    .grp-block { background:var(--surface); border:1px solid var(--border); border-radius:var(--rl); padding:1.25rem 1.5rem; margin-bottom:1.25rem; }\n    .grp-label { font-size:11px; font-weight:500; letter-spacing:.1em; text-transform:uppercase; color:var(--text3); margin-bottom:1rem; margin-top:1.25rem; padding-bottom:.5rem; border-bottom:1px solid var(--border); }\n    .grp-block .grp-label { margin-top:0; }\n    .grp-sub { font-size:12px; font-weight:500; color:var(--text2); margin-bottom:.6rem; margin-top:1.25rem; display:flex; align-items:center; gap:6px; }\n    .grp-sub::before { content:''; display:inline-block; width:7px; height:7px; border-radius:50%; background:var(--text3); flex-shrink:0; }\n\n    /* financial health table */\n    .fh-grid { display:flex; flex-direction:column; gap:0; border:1px solid var(--border); border-radius:var(--rl); overflow:hidden; }\n    .fh-row { display:grid; grid-template-columns:1fr 140px; align-items:start; padding:14px 14px; border-bottom:1px solid var(--surface2); background:var(--surface); gap:12px; }\n    .fh-row:last-child { border-bottom:none; }\n    .fh-row:nth-child(even) { background:#fafaf8; }\n    .fh-name { font-size:13px; font-weight:500; color:var(--text); margin-bottom:1px; }\n    .fh-fml { font-size:11px; color:var(--text3); font-style:italic; }\n    .fh-bench { font-size:10px; color:var(--amber); margin-top:1px; }\n    .fh-right { display:flex; flex-direction:column; align-items:flex-end; gap:3px; }\n    .fh-val { font-family:'DM Mono',monospace; font-size:15px; font-weight:500; }\n\n    .kpi-val.surplus { color:#1a6b47; font-weight:700; }\n    .kpi-val.deficit { color:#8b2020; font-weight:700; }\n    \n    /* commentary */\n    .commentary-wrap { margin-top:8px; }\n    .commentary-lbl { font-size:10px; font-weight:500; letter-spacing:.05em; text-transform:uppercase; color:var(--text3); margin-bottom:4px; display:flex; align-items:center; gap:4px; }\n    .commentary-char { font-weight:400; letter-spacing:0; text-transform:none; margin-left:auto; }\n    .commentary-box { width:100%; border:1px solid var(--border); border-radius:var(--r); padding:8px 10px; font-size:12px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface2); resize:vertical; line-height:1.5; transition:border-color .12s; }\n    .commentary-box:focus { outline:none; border-color:var(--text); background:var(--surface); }\n    .commentary-box::placeholder { color:var(--text3); }\n    .commentary-print { display:none; font-size:11px; color:var(--text2); font-style:italic; margin-top:6px; white-space:pre-wrap; }\n    \n    /* Reset buttons */\n    .btn-reset-seg { display:inline-flex; align-items:center; gap:5px; padding:5px 12px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; }\n    .btn-reset-seg:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .btn-reset-data { display:inline-flex; align-items:center; gap:4px; padding:4px 9px; border:1px solid var(--border); border-radius:var(--r); background:transparent; font-size:11px; font-family:'DM Sans',sans-serif; color:var(--text3); cursor:pointer; transition:all .12s; margin-left:6px; }\n    .btn-reset-data:hover { border-color:#c0392b; color:#c0392b; background:#fff5f5; }\n    .seg-hdr-actions { display:flex; align-items:center; gap:8px; flex-wrap:wrap; justify-content:flex-end; }\n\n    /* Commentary box style override */\n    .commentary-block { margin-bottom:1.25rem; }\n    .commentary-box { width:100%; min-height:100px; border:1px solid var(--border); border-radius:var(--rl); padding:12px 14px; font-size:13px; font-family:'DM Sans',sans-serif; color:var(--text); background:var(--surface); resize:vertical; line-height:1.6; transition:border-color .12s; }\n    .commentary-box:focus { outline:none; border-color:var(--text); }\n    .commentary-box::placeholder { color:var(--text3); }\n    .commentary-lbl { font-size:11px; font-weight:500; letter-spacing:.06em; text-transform:uppercase; color:var(--text3); margin-bottom:6px; display:flex; align-items:center; gap:6px; }\n    .commentary-char { font-size:10px; color:var(--text3); margin-left:auto; font-weight:400; letter-spacing:0; text-transform:none; }\n\n    /* Formula display block */\n    .formula-card {\n      background: var(--surface2);\n      border-radius: var(--r);\n      padding: 12px;\n      margin: 10px 0;\n      font-size: 12px;\n      overflow-x: auto;\n      border-left: 3px solid var(--blue);\n    }\n    .math-title {\n      font-weight: 500;\n      color: var(--text2);\n      font-size: 11px;\n      margin-bottom: 4px;\n      text-transform: uppercase;\n      letter-spacing: 0.04em;\n    }\n\n    /* Print styles */\n    @media print {\n      * { -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important; }\n      body { background:#f7f6f2 !important; margin:0; }\n      .topbar, .sidebar, #page-entry, .btn-pdf, .pdf-overlay,\n      .btn-reset-seg, .btn-reset-data, .seg-nav, .commentary-box,\n      .commentary-lbl, .commentary-char, .pill-nav { display:none !important; }\n      #page-analysis { display:block !important; min-height:auto !important; }\n      #page-analysis .main-area { padding:12px !important; max-width:100% !important; }\n      .page.active { display:block !important; }\n      /* Print commentary text in place of textarea */\n      .commentary-print { display:block !important; }\n      /* Prevent frames splitting across pages */\n      .grp-block { break-inside:avoid; page-break-inside:avoid; margin-bottom:10px !important; padding:12px !important; border:1px solid #e2dfd8 !important; border-radius:8px !important; }\n      .quad-grid, .quad-card { break-inside:avoid; page-break-inside:avoid; }\n      .fh-row { break-inside:avoid; page-break-inside:avoid; }\n      .a-card { break-inside:avoid; page-break-inside:avoid; margin-bottom:8px !important; }\n      .nw-duo-grid { break-inside:avoid; page-break-inside:avoid; }\n      .kpi-grid { grid-template-columns:repeat(4,1fr) !important; break-inside:avoid; }\n      .two-col { break-inside:avoid; }\n      .chart-wrap { break-inside:avoid; }\n      .a-header { break-after:avoid; }\n      .grp-label { break-after:avoid; font-size:9px !important; }\n    }\n\n    /* Print button \u2014 replaces PDF btn */\n    .btn-pdf { display:inline-flex; align-items:center; gap:7px; padding:8px 18px; background:var(--text); color:#fff; border:none; border-radius:var(--r); font-size:13px; font-family:'DM Sans',sans-serif; font-weight:500; cursor:pointer; transition:opacity .15s; white-space:nowrap; flex-shrink:0; }\n    .btn-pdf:hover { opacity:.85; }\n    .a-header { display:flex; align-items:flex-start; justify-content:space-between; gap:1rem; margin-bottom:1.75rem; flex-wrap:wrap; }\n    .a-header-left .a-title { font-size:28px; font-weight:300; letter-spacing:-.03em; }\n    .a-header-left .a-sub { font-size:13px; color:var(--text3); margin-top:4px; }\n    .pdf-overlay { display:none; position:fixed; inset:0; background:rgba(0,0,0,.45); z-index:9999; align-items:center; justify-content:center; }\n    .pdf-overlay.show { display:flex; }\n    .pdf-box { background:var(--surface); border-radius:var(--rl); padding:1.5rem 2rem; text-align:center; min-width:240px; box-shadow:0 8px 32px rgba(0,0,0,.18); }\n    .pdf-box p { font-size:13px; color:var(--text2); margin-top:8px; }\n    .pdf-spinner { width:32px; height:32px; border:3px solid var(--border); border-top-color:var(--text); border-radius:50%; animation:spin .7s linear infinite; margin:0 auto 8px; }\n    @keyframes spin { to { transform:rotate(360deg); } }\n\n    @media(max-width:760px){\n      .sidebar{display:none;}\n      .kpi-grid,.mx-grid,.quad-grid{grid-template-columns:1fr 1fr;}\n      .two-col{grid-template-columns:1fr;}\n      .fh-row{grid-template-columns:1fr;}\n      .topbar{height:auto;min-height:56px;gap:10px;flex-wrap:wrap;padding:.75rem 1rem}\n      .pill-nav{order:2}\n    }\n\n    @media(max-width:480px){\n      .kpi-grid,.mx-grid,.quad-grid{grid-template-columns:1fr;}\n      .nw-duo-grid{grid-template-columns:1fr;}\n    }\n\n    /* Additional custom action plan classes */\n    .ap-item { display: flex; align-items: flex-start; gap: 10px; padding: 10px 0; border-bottom: 1px solid var(--border); }\n    .ap-item:last-child { border-bottom: none; }\n    .ap-icon { display: flex; align-items: center; justify-content: center; width: 20px; height: 20px; border-radius: 50%; color: #fff; font-size: 11px; flex-shrink: 0; margin-top: 2px; }\n    .ap-icon.check { background: var(--green); }\n    .ap-icon.alert { background: var(--orange); }\n    .ap-text { font-size: 12.5px; color: var(--text2); }\n    .ap-text strong { color: var(--text); }\n  \n    .math-render { font-family: 'DM Mono', monospace; font-size: 15px; line-height: 1.7; margin-top: 8px; padding: 10px 12px; background: var(--surface2); border: 1px solid var(--border); border-radius: var(--r); color: var(--text); }\n    .math-render sub { font-size: 70%; }\n    .math-render sup { font-size: 70%; }\n  /* Hidden per Planning Suite requirement */\n    .formula-card { display: none !important; }\n</style>\n\n<style id=\"planning-suite-frame-overrides\">\n  html, body { min-height: 100%; }\n  body { margin: 0 !important; padding: 0 !important; background: #f7f6f2 !important; }\n  .topbar, .sidebar { display: none !important; }\n  .page.active { min-height: 100vh !important; display: block !important; }\n  .main-area { width: 100% !important; max-width: 1240px !important; margin: 0 auto !important; padding: 2rem !important; box-sizing: border-box !important; }\n  .container { max-width: 1240px !important; padding: 2rem !important; }\n  @media (max-width: 900px) { .main-area, .container { padding: 1rem !important; } .f-static { grid-template-columns: 1fr !important; } }\n</style>\n</head>\n<body>\n\n  <!-- \u2500\u2500 TOPBAR \u2500\u2500 -->\n  <header class=\"topbar\">\n    <div class=\"brand\">\n      <div class=\"brand-mark\">\n        <svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\">\n          <path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-6h2v6zm0-8h-2V7h2v2z\"/>\n        </svg>\n      </div>\n      <div>\n        <span class=\"brand-name\">ProRetire Plan\u2122</span>\n        <span class=\"brand-sub\">EPF & Gap Analyzer</span>\n      </div>\n    </div>\n\n    <!-- Navigation Tabs -->\n    <div class=\"pill-nav\">\n      <button class=\"pill-btn active\" id=\"btn-tab-entry\" onclick=\"switchPage('entry')\">Inputs & Modeling</button>\n      <button class=\"pill-btn\" id=\"btn-tab-analysis\" onclick=\"switchPage('analysis')\">Retirement Gap Analysis</button>\n    </div>\n\n    <!-- Global Actions -->\n    <div class=\"seg-hdr-actions\">\n      <button class=\"btn-reset-data\" onclick=\"resetAllData()\">\n        <svg style=\"width:11px; height:11px; vertical-align:middle; margin-right:3px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8M21 3v5h-5M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16M3 21v-5h5\"/></svg>\n        Reset Form\n      </button>\n    </div>\n  </header>\n\n  <!-- \u2500\u2500 PAGE 1: ENTRY LAYOUT \u2500\u2500 -->\n  <div id=\"page-entry\" class=\"page active\">\n    <!-- Sidebar navigation & dynamic summary -->\n    <aside class=\"sidebar\">\n      <div class=\"prog-wrap\">\n        <div class=\"prog-top\">\n          <span>Profile Progress</span>\n          <span id=\"prog-pct\">60%</span>\n        </div>\n        <div class=\"prog-track\">\n          <div class=\"prog-fill\" id=\"prog-fill\" style=\"width: 60%;\"></div>\n        </div>\n      </div>\n\n      <div class=\"sb-label\">Input Sections</div>\n      <a href=\"javascript:void(0)\" class=\"sb-item active\" id=\"nav-seg-1\" onclick=\"switchSegment(1)\">\n        <span class=\"sb-dot d1\"></span>\n        1. Income & Fund Needs\n      </a>\n      <a href=\"javascript:void(0)\" class=\"sb-item\" id=\"nav-seg-2\" onclick=\"switchSegment(2)\">\n        <span class=\"sb-dot d2\"></span>\n        2. EPF Growth Projection\n      </a>\n      <a href=\"javascript:void(0)\" class=\"sb-item\" id=\"nav-seg-3\" onclick=\"switchSegment(3)\">\n        <span class=\"sb-dot d3\"></span>\n        3. Other Assets & Gap\n      </a>\n\n      <!-- Segment Dynamic Summaries inside Sidebar -->\n      <div style=\"margin-top: 20px;\"></div>\n      <div class=\"sb-label\">Live Calculation Preview</div>\n      \n      <!-- Preview Segment 1 -->\n      <div class=\"seg-sum on\" id=\"sum-seg-1\">\n        <div class=\"ss-head qg\">Needs Summary</div>\n        <div class=\"ss-body\">\n          <div class=\"ss-row\">\n            <span>Inflation adjusted:</span>\n            <span class=\"ss-v\" id=\"lbl-inflation-rate\">3.00%</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>1st Yr Needs (FV):</span>\n            <span class=\"ss-v ss-b text-blue\" id=\"lbl-yr1-fv\">RM 0.00</span>\n          </div>\n          <div class=\"ss-div\"></div>\n          <div class=\"ss-tot\">\n            <span>Fund Needed:</span>\n            <span class=\"ss-v ss-b positive\" id=\"lbl-fund-needed\">RM 0.00</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- Preview Segment 2 -->\n      <div class=\"seg-sum on\" id=\"sum-seg-2\">\n        <div class=\"ss-head qb\">EPF Projection</div>\n        <div class=\"ss-body\">\n          <div class=\"ss-row\">\n            <span>Years to Retire:</span>\n            <span class=\"ss-v\" id=\"lbl-epf-years\">25 yrs</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Annual Salary:</span>\n            <span class=\"ss-v\" id=\"lbl-epf-salary\">RM 60,000</span>\n          </div>\n          <div class=\"ss-div\"></div>\n          <div class=\"ss-tot\">\n            <span>Projected EPF:</span>\n            <span class=\"ss-v ss-b neutral\" id=\"lbl-projected-epf\">RM 0.00</span>\n          </div>\n        </div>\n      </div>\n\n      <!-- Preview Segment 3 -->\n      <div class=\"seg-sum on\" id=\"sum-seg-3\">\n        <div class=\"ss-head qo\">Gap Status</div>\n        <div class=\"ss-body\">\n          <div class=\"ss-row\">\n            <span>Total Expected:</span>\n            <span class=\"ss-v\" id=\"lbl-total-available\">RM 0.00</span>\n          </div>\n          <div class=\"ss-row\">\n            <span>Total Needed:</span>\n            <span class=\"ss-v\" id=\"lbl-total-needed-side\">RM 0.00</span>\n          </div>\n          <div class=\"ss-div\"></div>\n          <div class=\"ss-tot\">\n            <span>Calculated Gap:</span>\n            <span class=\"ss-v ss-b\" id=\"lbl-current-gap\">RM 0.00</span>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- Main Content Area with segments -->\n    <main class=\"main-area\">\n      \n      <!-- SEGMENT 1: Income Needs & Fund Needed -->\n      <section class=\"segment active\" id=\"segment-1\">\n        <div class=\"seg-hdr\">\n          <div>\n            <span class=\"seg-tag t1\">Section 1</span>\n            <h1 class=\"seg-title\">Retirement Income &amp; Fund Needs</h1>\n            <p class=\"seg-desc\">Estimate the future cost of your lifestyle at retirement using financial math models.</p>\n          </div>\n          <div class=\"seg-tot-box\">\n            <span class=\"tot-label\">Est. Year 1 Needs (FV)</span>\n            <div class=\"tot-val\" id=\"val-hdr-y1-needs\">RM 0.00</div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci1\">1A</div>\n              <div>\n                <span class=\"ch-title\">Demographics &amp; Timing Setup</span>\n                <span class=\"ch-sub\">Required timelines for calculations</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Current Age</span>\n                <span class=\"f-sub\">Your current age (years)</span>\n              </div>\n              <div>\n                <input type=\"text\" class=\"inp\" id=\"inp-current-age\" min=\"18\" max=\"100\" value=\"30\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Retirement Age for EPF Withdrawal</span>\n                <span class=\"f-sub\">Age you plan to retire (must be between 55 to 60)</span>\n              </div>\n              <div>\n                <input type=\"text\" class=\"inp\" id=\"inp-retirement-age\" min=\"55\" max=\"60\" value=\"55\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Life Expectancy</span>\n                <span class=\"f-sub\">Expected lifespan (years)</span>\n              </div>\n              <div>\n                <input type=\"text\" class=\"inp\" id=\"inp-life-expectancy\" min=\"60\" max=\"120\" value=\"80\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci1\">1B</div>\n              <div>\n                <span class=\"ch-title\">Current Income &amp; Expenses Settings</span>\n                <span class=\"ch-sub\">Used to determine future purchasing needs</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Current Annual Salary (RM)</span>\n                <span class=\"f-sub\">Base gross yearly salary</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">RM</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-annual-salary\" min=\"0\" value=\"60000\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Current Annual Expenses (RM)</span>\n                <span class=\"f-sub\">Your total estimated yearly outflows today</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">RM</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-annual-expenses\" min=\"0\" value=\"36000\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci1\">1C</div>\n              <div>\n                <span class=\"ch-title\">1st Year Income Need Formula Options</span>\n                <span class=\"ch-sub\">Define Present Value (PV) and inflation rates</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Present Value (PV) Foundation Selection</span>\n                <span class=\"f-sub\">Choose how to anchor your retirement cost base</span>\n              </div>\n              <div>\n                <select class=\"inp-t\" id=\"sel-pv-type\" onchange=\"togglePVPercentUI(); triggerCalculations();\" style=\"font-size:12.5px;\">\n                  <option value=\"percentage\">Percentage of Current Annual Salary</option>\n                  <option value=\"expenses\">Current Annual Expenses</option>\n                </select>\n              </div>\n            </div>\n\n            <div class=\"f-static\" id=\"row-pv-percentage\">\n              <div>\n                <span class=\"f-label\">Income Replacement Target (%)</span>\n                <span class=\"f-sub\">Expected retirement expenses (30% to 100%)</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-salary-pct\" min=\"30\" max=\"100\" value=\"70\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Inflation Rate Pre-Retirement (%)</span>\n                <span class=\"f-sub\">Used to project today's dollar to retirement day</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-inflation-pre\" step=\"0.1\" value=\"3.0\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Inflation Rate After-Retirement (%)</span>\n                <span class=\"f-sub\">Cost increase during retirement years</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-inflation-post\" step=\"0.1\" value=\"3.0\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"formula-card\">\n              <div class=\"math-title\">Calculated Using Future Value Formulation</div>\n              <div class=\"math-render\">FV = PV \u00d7 (1 + i<sub>pre</sub>)<sup>n</sup></div>\n              <p style=\"margin-top:4px; font-size:11px; color:var(--text2);\">\n                Where <strong>PV</strong> = <span id=\"eq-pv-source\">70% x RM 60,000 = RM 42,000</span>, \n                <strong>Period (n)</strong> = <span id=\"eq-period\">25</span> years (Retirement Age - Current Age), and \n                <strong>Rate (i<sub>pre</sub>)</strong> = <span id=\"eq-rate\">3%</span>.\n              </p>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">1C Calculated 1st Year Income Need</span>\n                <span class=\"f-sub\">Future value result using inputs from 1A and 1B</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <input type=\"text\" class=\"inp\" id=\"lbl-1c-result\" readonly value=\"RM 0.00\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci1\">1D</div>\n              <div>\n                <span class=\"ch-title\">Retirement Capitalization Method</span>\n                <span class=\"ch-sub\">Select strategy for generating retirement funds</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Capitalization Method Selection</span>\n                <span class=\"f-sub\">Liquidation (gradually spend down) vs Intact (preserves principal)</span>\n              </div>\n              <div>\n                <select class=\"inp-t\" id=\"sel-capitalization-method\" onchange=\"triggerCalculations()\" style=\"font-size:12.5px; font-weight:bold;\">\n                  <option value=\"liquidation\" selected>Capital Liquidation Method (Spend Down Capital)</option>\n                  <option value=\"intact\">Capital Intact Method (Preserve Principal Capital)</option>\n                </select>\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Nominal Rate of Return During Retirement (%)</span>\n                <span class=\"f-sub\">Expected average return of capital while retired</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-return-retirement\" step=\"0.1\" value=\"5.5\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Real Adjusted Rate of Return ($r_{\\text{adj}}$)</span>\n                <span class=\"f-sub\">Return adjusted for post-retirement inflation</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"lbl-real-return\" readonly value=\"2.43%\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n\n            <div class=\"formula-card\" id=\"formula-liquidation-block\">\n              <div class=\"math-title\">Capital Liquidation Formula (Annuity Due / Beginning Mode)</div>\n              <div class=\"math-render\">PV<sub>need</sub> = PMT \u00d7 [(1 \u2212 (1 + r<sub>adj</sub>)<sup>\u2212N</sup>) \u00f7 r<sub>adj</sub>] \u00d7 (1 + r<sub>adj</sub>)</div>\n              <p style=\"margin-top:4px; font-size:11px; color:var(--text2);\">\n                Where <strong>PMT</strong> = 1st Year Income Need, \n                <strong>r<sub>adj</sub></strong> = Real Adjusted Return, and \n                <strong>N</strong> = <span id=\"eq-post-n\">25</span> years of retirement (Life Expectancy - Retirement Age).\n              </p>\n            </div>\n\n            <div class=\"formula-card\" id=\"formula-intact-block\" style=\"display:none;\">\n              <div class=\"math-title\">Capital Intact Formula</div>\n              <div class=\"math-render\">PV<sub>need</sub> = PMT \u00f7 r<sub>adj</sub></div>\n              <p style=\"margin-top:4px; font-size:11px; color:var(--text2);\">\n                Yielding perpetual income without exhausting the principal fund base.\n              </p>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">1D Calculated Retirement Capital Required</span>\n                <span class=\"f-sub\">Calculated from the 1C result and selected capitalization method</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <input type=\"text\" class=\"inp\" id=\"lbl-1d-result\" readonly value=\"RM 0.00\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"seg-nav\">\n          <div></div>\n          <button class=\"btn-nav btn-pri\" onclick=\"switchSegment(2)\">\n            Next: EPF Projection\n            <svg style=\"width:14px; height:14px; margin-left:4px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n          </button>\n        </div>\n      </section>\n\n      <!-- SEGMENT 2: EPF PROJECTIONS -->\n      <section class=\"segment\" id=\"segment-2\">\n        <div class=\"seg-hdr\">\n          <div>\n            <span class=\"seg-tag t2\">Section 2</span>\n            <h1 class=\"seg-title\">Employee Provident Fund (EPF) Projection</h1>\n            <p class=\"seg-desc\">Calculate your projected statutory EPF retirement savings incorporating compound wage growth.</p>\n          </div>\n          <div class=\"seg-tot-box\">\n            <span class=\"tot-label\">Est. Projected EPF Fund</span>\n            <div class=\"tot-val text-blue\" id=\"val-hdr-epf-proj\">RM 0.00</div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci2\">2A</div>\n              <div>\n                <span class=\"ch-title\">Statutory Contributions &amp; Wage Growth Inputs</span>\n                <span class=\"ch-sub\">Required components for compounding projection calculations</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Current EPF Balance (RM)</span>\n                <span class=\"f-sub\">Initial EPF balance today ($FV_1$ principal base)</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">RM</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-current-epf\" min=\"0\" value=\"50000\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Salary Increment Rate ($G$) (%)</span>\n                <span class=\"f-sub\">Average expected annual salary rise %</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-salary-increment\" step=\"0.1\" value=\"4.0\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">Total EPF Contribution (%)</span>\n                <span class=\"f-sub\">Combined employer + employee statutory percentage contribution</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-epf-contribution-rate\" step=\"0.5\" value=\"24.0\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">EPF Dividend/Growth Rate ($R$) (%)</span>\n                <span class=\"f-sub\">Average annual dividend return paid by EPF</span>\n              </div>\n              <div class=\"pfx-wrap\">\n                <span class=\"pfx\">%</span>\n                <input type=\"text\" class=\"inp pl\" id=\"inp-epf-growth-rate\" step=\"0.1\" value=\"5.5\" oninput=\"triggerCalculations()\">\n              </div>\n            </div>\n\n            <div class=\"formula-card\">\n              <div class=\"math-title\">Statutory EPF Compound Accumulation Modeling</div>\n              <div class=\"math-render\">FV<sub>2</sub> = FV<sub>1</sub> + PMT \u00d7 [((1 + R)<sup>n</sup> \u2212 (1 + G)<sup>n</sup>) \u00f7 (R \u2212 G)]</div>\n              <p style=\"margin-top:6px; font-size:11px; color:var(--text2); line-height: 1.5;\">\n                Where:<br>\n                \u2022 <strong>$FV_2$</strong> = Total Projected EPF Balance at retirement.<br>\n                \u2022 <strong>$FV_1$</strong> = Projected value of current balance $= PV_{\\text{epf}} \\times (1 + R)^n$.<br>\n                \u2022 <strong>$PMT$</strong> = 1C Calculated 1st Year Income Need.<br>\n                \u2022 <strong>$R$</strong> = EPF Dividend rate, <strong>$G$</strong> = Salary Increment rate, and <strong>$n$</strong> = years to retirement (<span id=\"eq-epf-n\">25</span>).\n              </p>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">2A FV<sub>1</sub>: Future Value of Current EPF Balance</span>\n                <span class=\"f-sub\">Current EPF Balance compounded to retirement age</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <input type=\"text\" class=\"inp\" id=\"lbl-fv1-result\" readonly value=\"RM 0.00\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">2A PMT Input</span>\n                <span class=\"f-sub\">Uses the calculated value from 1C</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <input type=\"text\" class=\"inp\" id=\"lbl-2a-pmt\" readonly value=\"RM 0.00\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n\n            <div class=\"f-static\">\n              <div>\n                <span class=\"f-label\">2A Calculated Projected EPF Balance</span>\n                <span class=\"f-sub\">FV<sub>2</sub> result using FV<sub>1</sub>, PMT, R, G and n</span>\n              </div>\n              <div class=\"pfx-wrap\" style=\"font-weight:bold;\">\n                <input type=\"text\" class=\"inp\" id=\"lbl-2a-result\" readonly value=\"RM 0.00\" style=\"background:var(--surface2);\">\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"seg-nav\">\n          <button class=\"btn-nav\" onclick=\"switchSegment(1)\">\n            <svg style=\"width:14px; height:14px; margin-right:4px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 12H5M12 19l-7-7 7-7\"/></svg>\n            Back: Fund Needs\n          </button>\n          <button class=\"btn-nav btn-pri\" onclick=\"switchSegment(3)\">\n            Next: Other Assets &amp; Gap\n            <svg style=\"width:14px; height:14px; margin-left:4px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M5 12h14M12 5l7 7-7 7\"/></svg>\n          </button>\n        </div>\n      </section>\n\n      <!-- SEGMENT 3: GAP ANALYSIS INPUTS -->\n      <section class=\"segment\" id=\"segment-3\">\n        <div class=\"seg-hdr\">\n          <div>\n            <span class=\"seg-tag t3\">Section 3</span>\n            <h1 class=\"seg-title\">Other Assets &amp; Gap Analysis</h1>\n            <p class=\"seg-desc\">Factor in other non-EPF retirement reserves to determine your net surplus or deficit.</p>\n          </div>\n          <div class=\"seg-tot-box\">\n            <span class=\"tot-label\">Est. Other Reserves Total</span>\n            <div class=\"tot-val text-gold\" id=\"val-hdr-other-reserves\">RM 0.00</div>\n          </div>\n        </div>\n\n        <div class=\"card\">\n          <div class=\"ch open\">\n            <div class=\"ch-left\">\n              <div class=\"ci ci3\">3A</div>\n              <div>\n                <span class=\"ch-title\">Custom Non-EPF Retirement Reserves</span>\n                <span class=\"ch-sub\">Add personal investments, unit trusts, or properties</span>\n              </div>\n            </div>\n          </div>\n          <div class=\"cb open\">\n            <p style=\"font-size:12.5px; color:var(--text2); margin-bottom:12px;\">\n              Input any additional financial capital earmarked for retirement to obtain an accurate picture.\n            </p>\n            \n            <div class=\"exp-rows\" id=\"other-funds-container\">\n              <!-- Dynamically generated rows -->\n            </div>\n\n            <button class=\"btn-add\" onclick=\"addNewFundRow()\">\n              <svg style=\"width:12px; height:12px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg>\n              Add New Retirement Resource / Fund\n            </button>\n          </div>\n        </div>\n\n        <!-- Call to Action Card -->\n        <div class=\"card\" style=\"background:var(--surface2); border: 2px solid var(--border-strong);\">\n          <div class=\"cb open\" style=\"text-align:center; padding: 2rem 1.5rem;\">\n            <h3 style=\"font-size:18px; font-weight:400; margin-bottom:8px;\">Ready to Calculate the Retirement Gap?</h3>\n            <p style=\"font-size:13px; color:var(--text2); margin-bottom:1.5rem; max-width:550px; margin-left:auto; margin-right:auto;\">\n              ProRetire Plan will compile Section 1 needs, Section 2 projected EPF savings, and Section 3 custom assets to generate a full visual diagnostics report.\n            </p>\n            \n            <button class=\"btn-pdf\" style=\"margin:0 auto; padding: 12px 24px; font-size:14px; border-radius:30px;\" onclick=\"calculateAndNavigateToAnalysis()\">\n              <svg style=\"width:16px; height:16px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/><polyline points=\"3.27 6.96 12 12.01 20.73 6.96\"/><line x1=\"12\" y1=\"22.08\" x2=\"12\" y2=\"12\"/></svg>\n              Find The Retirement Fund Gap\n            </button>\n          </div>\n        </div>\n\n        <div class=\"seg-nav\">\n          <button class=\"btn-nav\" onclick=\"switchSegment(2)\">\n            <svg style=\"width:14px; height:14px; margin-right:4px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 12H5M12 19l-7-7 7-7\"/></svg>\n            Back: EPF Growth\n          </button>\n          <div></div>\n        </div>\n      </section>\n    </main>\n  </div>\n\n  <!-- \u2500\u2500 PAGE 2: ANALYSIS DISPLAY (DASHBOARD) \u2500\u2500 -->\n  <div id=\"page-analysis\" class=\"page\">\n    <main class=\"main-area\">\n      <div class=\"a-header\">\n        <div class=\"a-header-left\">\n          <span class=\"seg-tag t2\" id=\"badge-status-result\">ANALYSIS REPORT</span>\n          <h1 class=\"a-title\">Retirement Readiness Diagnostics</h1>\n          <p class=\"a-sub\">Consolidated balance sheet, inflation models, and gap analysis results.</p>\n        </div>\n        <div class=\"seg-hdr-actions\">\n          <button class=\"btn-pdf\" onclick=\"triggerPrint()\">\n            <svg style=\"width:14px; height:14px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"6 9 6 2 18 2 18 9\"/><path d=\"M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2\"/><rect x=\"6\" y=\"14\" width=\"12\" height=\"8\"/></svg>\n            Print Diagnostics Report\n          </button>\n        </div>\n      </div>\n\n      <!-- Live Notification Banner -->\n      <div id=\"banner-result-box\" class=\"grp-block\" style=\"border:1px solid var(--border); border-left: 5px solid var(--green); background:var(--surface);\">\n        <h3 id=\"diag-banner-title\" style=\"font-size:16px; font-weight:600; margin-bottom:4px;\">Diagnostic Assessment</h3>\n        <p id=\"diag-banner-desc\" style=\"font-size:13px; color:var(--text2);\">Calculating evaluation...</p>\n      </div>\n\n      <div class=\"sec-title\">Core Balance Sheet Metrics</div>\n\n      <!-- Quadrant Cards Summary -->\n      <div class=\"quad-grid\">\n        <div class=\"quad-card\">\n          <div class=\"q-head qr\">\n            Total Fund Needed \n            <span class=\"q-hint\" id=\"diag-method-badge\">Capital Liquidation</span>\n          </div>\n          <div class=\"q-body\">\n            <div class=\"q-row\">\n              <span>Inflation Base Yr 1 PMT:</span>\n              <span class=\"q-val\" id=\"diag-y1-pmt\">RM 0.00</span>\n            </div>\n            <div class=\"q-row\">\n              <span>Compounding Period:</span>\n              <span class=\"q-val\" id=\"diag-pre-period\">25 yrs</span>\n            </div>\n            <div class=\"q-row\">\n              <span>Retirement Span:</span>\n              <span class=\"q-val\" id=\"diag-post-period\">25 yrs</span>\n            </div>\n            <div class=\"q-div\"></div>\n            <div class=\"q-foot\">\n              <span>TOTAL CAPITAL NEED:</span>\n              <span class=\"q-fv negative\" id=\"diag-total-needed\">RM 0.00</span>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"quad-card\">\n          <div class=\"q-head qg\">\n            Accumulated Resources\n            <span class=\"q-hint\">Projected to Retirement</span>\n          </div>\n          <div class=\"q-body\">\n            <div class=\"q-row\">\n              <span>Projected EPF ($FV_2$):</span>\n              <span class=\"q-val\" id=\"diag-epf-fv2\">RM 0.00</span>\n            </div>\n            <div class=\"q-row\">\n              <span>Other Asset Portfolio:</span>\n              <span class=\"q-val\" id=\"diag-other-portfolio\">RM 0.00</span>\n            </div>\n            <div class=\"q-row\">\n              <span>Personal Additions:</span>\n              <span class=\"q-val\" id=\"diag-additions-val\">RM 0.00</span>\n            </div>\n            <div class=\"q-div\"></div>\n            <div class=\"q-foot\">\n              <span>TOTAL ACCUMULATION:</span>\n              <span class=\"q-fv positive\" id=\"diag-total-available\">RM 0.00</span>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Large Gap Display Card -->\n      <div class=\"nw-duo-grid\">\n        <div class=\"nw-card\">\n          <div class=\"nw-card-lbl\">\n            NET CAPITAL POSITION\n          </div>\n          <div class=\"nw-card-fml\">Total Accumulation Less Retirement Target Needs</div>\n          <div class=\"nw-val\" id=\"diag-net-position-val\">RM 0.00</div>\n          <div style=\"margin-top:10px;\">\n            <span class=\"nw-epf-tag with-epf\" id=\"diag-adequacy-tag\">Calculating</span>\n          </div>\n        </div>\n\n        <div class=\"nw-card\">\n          <div class=\"nw-card-lbl\">\n            RESOURCES TO TARGET RATIO (%)\n          </div>\n          <div class=\"nw-card-fml\">Funding completeness coverage ratio</div>\n          <div class=\"nw-val\" id=\"diag-adequacy-ratio\">0.0%</div>\n          <div style=\"margin-top:10px;\">\n            <div class=\"ratio-track\">\n              <div class=\"ratio-fill\" id=\"diag-ratio-bar\" style=\"width:0%; background:var(--green);\"></div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"two-col\">\n        <!-- Visual Asset Composition Chart / Bar list -->\n        <div class=\"a-card\">\n          <div class=\"a-card-title\">\n            <span class=\"a-dot\" style=\"background:var(--blue);\"></span>\n            Portfolio Composition at Retirement\n          </div>\n          <div class=\"bar-list\">\n            <div>\n              <div class=\"bar-item-top\">\n                <span class=\"bar-lbl\">Projected EPF Account Value</span>\n                <span class=\"bar-val\" id=\"bar-lbl-epf-val\">RM 0.00</span>\n              </div>\n              <div class=\"bar-track\">\n                <div class=\"bar-fill\" id=\"bar-fill-epf\" style=\"width:0%; background:var(--blue);\"></div>\n              </div>\n            </div>\n\n            <div>\n              <div class=\"bar-item-top\">\n                <span class=\"bar-lbl\">Additional Personal Savings &amp; Assets</span>\n                <span class=\"bar-val\" id=\"bar-lbl-other-val\">RM 0.00</span>\n              </div>\n              <div class=\"bar-track\">\n                <div class=\"bar-fill\" id=\"bar-fill-other\" style=\"width:0%; background:var(--gold);\"></div>\n              </div>\n            </div>\n\n            <div style=\"margin-top:12px; padding-top:10px; border-top:1px dashed var(--border);\">\n              <div class=\"bar-item-top\" style=\"font-weight:bold;\">\n                <span class=\"bar-lbl\">Target Capital Fund Requirement</span>\n                <span class=\"bar-val\" id=\"bar-lbl-total-req\">RM 0.00</span>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <!-- Metric Table -->\n        <div class=\"a-card\">\n          <div class=\"a-card-title\">\n            <span class=\"a-dot\" style=\"background:var(--gold);\"></span>\n            Detailed Component Balances\n          </div>\n          <table class=\"bk-table\">\n            <thead>\n              <tr>\n                <th>Component Segment</th>\n                <th style=\"text-align:right;\">Projected Value (RM)</th>\n              </tr>\n            </thead>\n            <tbody id=\"analysis-table-body\">\n              <!-- Dynamically populated rows -->\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <!-- Action Plan Recommendations Card -->\n      <div class=\"grp-block\">\n        <div class=\"grp-label\">Personalized Action Steps &amp; Recommendations</div>\n        <div id=\"action-plan-container\">\n          <!-- Dynamically populated list of personalized financial action plans -->\n        </div>\n      </div>\n\n      <!-- Section: Commentary Area (Persists and saves locally) -->\n      <div class=\"card\">\n        <div class=\"ch open\">\n          <div class=\"ch-left\">\n            <svg style=\"width:16px; height:16px; color:var(--text2);\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/></svg>\n            <span class=\"ch-title\">Planner Analysis Commentary</span>\n          </div>\n        </div>\n        <div class=\"cb open\">\n          <div class=\"commentary-block\">\n            <div class=\"commentary-lbl\">\n              Write Analysis Notes\n              <span class=\"commentary-char\" id=\"comm-char-cnt\">0 / 1000 characters</span>\n            </div>\n            <textarea class=\"commentary-box\" id=\"inp-commentary\" placeholder=\"Write down structural action plans, observations, and decisions based on these projections...\" maxlength=\"1000\" oninput=\"saveAndCountCommentary()\"></textarea>\n            <!-- Print mode text copy -->\n            <div class=\"commentary-print\" id=\"lbl-commentary-print\"></div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"seg-nav\">\n        <button class=\"btn-nav\" onclick=\"switchPage('entry')\">\n          <svg style=\"width:14px; height:14px; margin-right:4px;\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 12H5M12 19l-7-7 7-7\"/></svg>\n          Modify Input Assumptions\n        </button>\n        <div></div>\n      </div>\n    </main>\n  </div>\n\n  <!-- Loading overlay for print rendering -->\n  <div class=\"pdf-overlay\" id=\"pdf-overlay\">\n    <div class=\"pdf-box\">\n      <div class=\"pdf-spinner\"></div>\n      <h3 style=\"font-size:15px; font-weight:600;\">Generating Document</h3>\n      <p>Formatting print stylesheet elements...</p>\n    </div>\n  </div>\n\n  <!-- \u2500\u2500 APP CONTROLLER LOGIC \u2500\u2500 -->\n  <script>\n\n    function parseNumber(value) {\n      const cleaned = String(value ?? '').replace(/,/g, '').trim();\n      const parsed = parseFloat(cleaned);\n      return Number.isFinite(parsed) ? parsed : 0;\n    }\n\n    function formatInputNumber(value) {\n      const str = String(value ?? '').replace(/,/g, '').trim();\n      if (str === '' || str === '-' || str === '.') return str;\n      const match = str.match(/^(-?\\d*)(\\.\\d*)?$/);\n      if (!match) return value;\n      const whole = match[1] || '0';\n      const decimal = match[2] || '';\n      return whole.replace(/\\B(?=(\\d{3})+(?!\\d))/g, ',') + decimal;\n    }\n\n    function enableCommaSeparatedInputs() {\n      const ids = new Set([\n        'inp-annual-salary',\n        'inp-annual-expenses',\n        'inp-current-epf'\n      ]);\n      document.querySelectorAll('input.inp').forEach(input => {\n        if (input.readOnly) return;\n        if (!ids.has(input.id) && !input.closest('#other-funds-container')) return;\n        input.value = formatInputNumber(input.value);\n        input.addEventListener('input', function () {\n          const cursorFromEnd = this.value.length - this.selectionStart;\n          this.value = formatInputNumber(this.value);\n          const nextPos = Math.max(0, this.value.length - cursorFromEnd);\n          try { this.setSelectionRange(nextPos, nextPos); } catch (_) {}\n        });\n      });\n    }\n\n    // State storage\n    let customFunds = [\n      { name: \"Unit Trust / Mutual Funds\", amount: 150000 },\n      { name: \"Private Retirement Scheme (PRS)\", amount: 45000 }\n    ];\n\n    // Initialize application\n    window.onload = function() {\n      // Load saved commentary if exists\n      if (localStorage.getItem(\"proretire_commentary\")) {\n        document.getElementById(\"inp-commentary\").value = localStorage.getItem(\"proretire_commentary\");\n      }\n      \n      // Seed initial custom funds\n      renderCustomFunds();\n      enableCommaSeparatedInputs();\n      // Run calculations\n      triggerCalculations();\n    };\n\n    // Toggle showing percentage input based on PV option\n    function togglePVPercentUI() {\n      const type = document.getElementById(\"sel-pv-type\").value;\n      const row = document.getElementById(\"row-pv-percentage\");\n      if (type === \"percentage\") {\n        row.style.display = \"grid\";\n      } else {\n        row.style.display = \"none\";\n      }\n    }\n\n    // Dynamic row generation for other assets\n    function renderCustomFunds() {\n      const container = document.getElementById(\"other-funds-container\");\n      container.innerHTML = \"\";\n      \n      customFunds.forEach((fund, index) => {\n        const row = document.createElement(\"div\");\n        row.className = \"exp-row\";\n        row.innerHTML = `\n          <input type=\"text\" class=\"inp-t\" value=\"${escapeHtml(fund.name)}\" placeholder=\"Asset / Fund Name\" oninput=\"updateFundName(${index}, this.value)\">\n          <div class=\"pfx-wrap\">\n            <span class=\"pfx\">RM</span>\n            <input type=\"text\" class=\"inp pl\" value=\"${fund.amount}\" placeholder=\"Amount\" oninput=\"updateFundAmount(${index}, this.value)\">\n          </div>\n          <button class=\"btn-rm\" onclick=\"removeFundRow(${index})\" title=\"Remove\">\u00d7</button>\n        `;\n        container.appendChild(row);\n      });\n\n      calculateOtherFundsTotal();\n    }\n\n    function addNewFundRow() {\n      customFunds.push({ name: \"Alternative Investment Base\", amount: 10000 });\n      renderCustomFunds();\n      triggerCalculations();\n    }\n\n    function removeFundRow(index) {\n      customFunds.splice(index, 1);\n      renderCustomFunds();\n      triggerCalculations();\n    }\n\n    function updateFundName(index, val) {\n      customFunds[index].name = val;\n      // save comments/state locally optionally\n    }\n\n    function updateFundAmount(index, val) {\n      customFunds[index].amount = parseNumber(val);\n      calculateOtherFundsTotal();\n      triggerCalculations();\n    }\n\n    function calculateOtherFundsTotal() {\n      const total = customFunds.reduce((sum, item) => sum + (item.amount || 0), 0);\n      document.getElementById(\"val-hdr-other-reserves\").innerText = formatCurrency(total);\n      return total;\n    }\n\n    // Multi-tab controller\n    function switchPage(pageId) {\n      document.getElementById(\"page-entry\").classList.remove(\"active\");\n      document.getElementById(\"page-analysis\").classList.remove(\"active\");\n      document.getElementById(\"btn-tab-entry\").classList.remove(\"active\");\n      document.getElementById(\"btn-tab-analysis\").classList.remove(\"active\");\n\n      if (pageId === \"entry\") {\n        document.getElementById(\"page-entry\").classList.add(\"active\");\n        document.getElementById(\"btn-tab-entry\").classList.add(\"active\");\n      } else {\n        document.getElementById(\"page-analysis\").classList.add(\"active\");\n        document.getElementById(\"btn-tab-analysis\").classList.add(\"active\");\n        // Scroll back to top of display\n        window.scrollTo(0, 0);\n      }\n    }\n\n    // Segment tracking inside entry page\n    function switchSegment(num) {\n      document.getElementById(\"segment-1\").classList.remove(\"active\");\n      document.getElementById(\"segment-2\").classList.remove(\"active\");\n      document.getElementById(\"segment-3\").classList.remove(\"active\");\n      \n      document.getElementById(\"nav-seg-1\").classList.remove(\"active\");\n      document.getElementById(\"nav-seg-2\").classList.remove(\"active\");\n      document.getElementById(\"nav-seg-3\").classList.remove(\"active\");\n\n      document.getElementById(`segment-${num}`).classList.add(\"active\");\n      document.getElementById(`nav-seg-${num}`).classList.add(\"active\");\n\n      // Progress bar updates\n      const pct = num === 1 ? \"40%\" : num === 2 ? \"70%\" : \"100%\";\n      document.getElementById(\"prog-pct\").innerText = pct;\n      document.getElementById(\"prog-fill\").style.width = pct;\n    }\n\n    // CORE COMPUTATION MATRIX\n    function triggerCalculations() {\n      // 1. Inputs\n      const curAge = parseInt(document.getElementById(\"inp-current-age\").value) || 30;\n      let retAge = parseInt(document.getElementById(\"inp-retirement-age\").value) || 55;\n      \n      // Enforce age boundary requirements\n      if (retAge < 55) retAge = 55;\n      if (retAge > 60) retAge = 60;\n      \n      const lifeExp = parseInt(document.getElementById(\"inp-life-expectancy\").value) || 80;\n      const curSalary = parseNumber(document.getElementById(\"inp-annual-salary\").value) || 0;\n      const curExpenses = parseNumber(document.getElementById(\"inp-annual-expenses\").value) || 0;\n      \n      const pvType = document.getElementById(\"sel-pv-type\").value;\n      const salaryPct = parseNumber(document.getElementById(\"inp-salary-pct\").value) || 70;\n      const infPre = (parseNumber(document.getElementById(\"inp-inflation-pre\").value) || 0) / 100;\n      const infPost = (parseNumber(document.getElementById(\"inp-inflation-post\").value) || 0) / 100;\n      \n      const capitalizationMethod = document.getElementById(\"sel-capitalization-method\").value;\n      const retReturn = (parseNumber(document.getElementById(\"inp-return-retirement\").value) || 0) / 100;\n\n      // Compound factors\n      const nPre = Math.max(0, retAge - curAge);\n      const nPost = Math.max(0, lifeExp - retAge);\n\n      // Section 1: Calculate PV Foundation\n      let pvBase = 0;\n      if (pvType === \"percentage\") {\n        pvBase = curSalary * (salaryPct / 100);\n        document.getElementById(\"eq-pv-source\").innerText = `${salaryPct}% x RM ${formatRawNumber(curSalary)} = RM ${formatRawNumber(pvBase)}`;\n      } else {\n        pvBase = curExpenses;\n        document.getElementById(\"eq-pv-source\").innerText = `Current Expenses = RM ${formatRawNumber(pvBase)}`;\n      }\n\n      // Update LaTeX strings in description programmatically\n      document.getElementById(\"eq-period\").innerText = nPre;\n      document.getElementById(\"eq-rate\").innerText = `${(infPre * 100).toFixed(1)}%`;\n      document.getElementById(\"eq-post-n\").innerText = nPost;\n      document.getElementById(\"lbl-inflation-rate\").innerText = `${(infPre * 100).toFixed(2)}%`;\n\n      // Year 1 Retirement Needs Future Value\n      const yr1NeedsFV = pvBase * Math.pow(1 + infPre, nPre);\n      document.getElementById(\"val-hdr-y1-needs\").innerText = formatCurrency(yr1NeedsFV);\n      document.getElementById(\"lbl-yr1-fv\").innerText = formatCurrency(yr1NeedsFV);\n      document.getElementById(\"lbl-1c-result\").value = formatCurrency(yr1NeedsFV);\n      \n      // Diagnostics Quadrant details\n      document.getElementById(\"diag-y1-pmt\").innerText = formatCurrency(yr1NeedsFV);\n      document.getElementById(\"diag-pre-period\").innerText = `${nPre} yrs`;\n      document.getElementById(\"diag-post-period\").innerText = `${nPost} yrs`;\n\n      // Real rate adjusted return ($r_{adj}$) formulation: (1 + R)/(1 + inflation) - 1\n      let rAdj = ((1 + retReturn) / (1 + infPost)) - 1;\n      document.getElementById(\"lbl-real-return\").value = `${(rAdj * 100).toFixed(2)}%`;\n\n      // Target Fund Needed calculations\n      let fundNeeded = 0;\n      if (capitalizationMethod === \"liquidation\") {\n        document.getElementById(\"formula-liquidation-block\").style.display = \"block\";\n        document.getElementById(\"formula-intact-block\").style.display = \"none\";\n        document.getElementById(\"diag-method-badge\").innerText = \"Capital Liquidation\";\n\n        if (rAdj === 0) {\n          fundNeeded = yr1NeedsFV * nPost;\n        } else {\n          // Beginning of period mode formulation (annuity due)\n          fundNeeded = yr1NeedsFV * ((1 - Math.pow(1 + rAdj, -nPost)) / rAdj) * (1 + rAdj);\n        }\n      } else {\n        document.getElementById(\"formula-liquidation-block\").style.display = \"none\";\n        document.getElementById(\"formula-intact-block\").style.display = \"block\";\n        document.getElementById(\"diag-method-badge\").innerText = \"Capital Intact\";\n\n        if (rAdj <= 0) {\n          fundNeeded = Infinity; // Avoid crash on negative adjusted real returns\n        } else {\n          fundNeeded = yr1NeedsFV / rAdj;\n        }\n      }\n\n      const validatedFundNeeded = isFinite(fundNeeded) ? fundNeeded : 0;\n      document.getElementById(\"lbl-fund-needed\").innerText = formatCurrency(validatedFundNeeded);\n      document.getElementById(\"lbl-1d-result\").value = formatCurrency(validatedFundNeeded);\n\n      // Section 2: EPF accumulation formulas\n      const curEPF = parseNumber(document.getElementById(\"inp-current-epf\").value) || 0;\n      const salInc = (parseNumber(document.getElementById(\"inp-salary-increment\").value) || 0) / 100;\n      const epfContribRate = (parseNumber(document.getElementById(\"inp-epf-contribution-rate\").value) || 0) / 100;\n      const epfGrowth = (parseNumber(document.getElementById(\"inp-epf-growth-rate\").value) || 0) / 100;\n\n      document.getElementById(\"eq-epf-n\").innerText = nPre;\n      document.getElementById(\"lbl-epf-years\").innerText = `${nPre} yrs`;\n      document.getElementById(\"lbl-epf-salary\").innerText = formatCurrency(curSalary);\n\n      // $FV_1$ computation = $PV_{epf} \\times (1 + R)^n$\n      const fv1 = curEPF * Math.pow(1 + epfGrowth, nPre);\n\n      // PMT is the calculated 1C value as requested\n      const pmtEPF = yr1NeedsFV;\n\n      // $FV_2$ EPF formula handling division by zero risk when R == G\n      let fv2 = 0;\n      if (Math.abs(epfGrowth - salInc) < 1e-6) {\n        // Safe limit fallback: $PMT \\times n \\times (1 + R)^{n-1}$\n        fv2 = fv1 + (pmtEPF * nPre * Math.pow(1 + epfGrowth, nPre - 1));\n      } else {\n        fv2 = fv1 + (pmtEPF * (Math.pow(1 + epfGrowth, nPre) - Math.pow(1 + salInc, nPre)) / (epfGrowth - salInc));\n      }\n\n      document.getElementById(\"lbl-fv1-result\").value = formatCurrency(fv1);\n      document.getElementById(\"lbl-2a-pmt\").value = formatCurrency(pmtEPF);\n      document.getElementById(\"lbl-2a-result\").value = formatCurrency(fv2);\n      document.getElementById(\"val-hdr-epf-proj\").innerText = formatCurrency(fv2);\n      document.getElementById(\"lbl-projected-epf\").innerText = formatCurrency(fv2);\n\n      // Section 3: Gap Analysis Compilation\n      const otherAssetsTotal = calculateOtherFundsTotal();\n      const totalAccumulation = fv2 + otherAssetsTotal;\n\n      document.getElementById(\"lbl-total-available\").innerText = formatCurrency(totalAccumulation);\n      document.getElementById(\"lbl-total-needed-side\").innerText = formatCurrency(validatedFundNeeded);\n\n      const calculatedGap = totalAccumulation - validatedFundNeeded;\n      const gapLabelElement = document.getElementById(\"lbl-current-gap\");\n      \n      gapLabelElement.innerText = formatCurrency(calculatedGap);\n      if (calculatedGap >= 0) {\n        gapLabelElement.className = \"ss-v ss-b positive\";\n      } else {\n        gapLabelElement.className = \"ss-v ss-b negative\";\n      }\n\n      // Populate diagnostics variables\n      document.getElementById(\"diag-epf-fv2\").innerText = formatCurrency(fv2);\n      document.getElementById(\"diag-other-portfolio\").innerText = formatCurrency(otherAssetsTotal);\n      document.getElementById(\"diag-total-needed\").innerText = formatCurrency(validatedFundNeeded);\n      document.getElementById(\"diag-total-available\").innerText = formatCurrency(totalAccumulation);\n      \n      const gapValDiv = document.getElementById(\"diag-net-position-val\");\n      gapValDiv.innerText = formatCurrency(calculatedGap);\n\n      // Coverage ratio\n      let ratio = 0;\n      if (validatedFundNeeded > 0) {\n        ratio = (totalAccumulation / validatedFundNeeded) * 100;\n      } else if (totalAccumulation > 0) {\n        ratio = 100;\n      }\n      \n      document.getElementById(\"diag-adequacy-ratio\").innerText = `${ratio.toFixed(1)}%`;\n      const ratioFill = document.getElementById(\"diag-ratio-bar\");\n      ratioFill.style.width = `${Math.min(100, ratio)}%`;\n\n      const statusBadge = document.getElementById(\"badge-status-result\");\n      const adequacyTag = document.getElementById(\"diag-adequacy-tag\");\n      const resultBanner = document.getElementById(\"banner-result-box\");\n      const bannerTitle = document.getElementById(\"diag-banner-title\");\n      const bannerDesc = document.getElementById(\"diag-banner-desc\");\n\n      if (calculatedGap >= 0) {\n        // Capital Surplus\n        statusBadge.className = \"seg-tag t1\";\n        statusBadge.innerText = \"ADEQUATE SURPLUS\";\n        \n        adequacyTag.className = \"nw-epf-tag with-epf\";\n        adequacyTag.innerText = \"FULLY SECURED SURPLUS\";\n        \n        ratioFill.style.background = \"var(--green)\";\n        gapValDiv.className = \"nw-val positive\";\n        \n        resultBanner.style.borderLeftColor = \"var(--green)\";\n        bannerTitle.innerText = \"Excellent News! Your Capital Target is Met.\";\n        bannerDesc.innerText = `Projections show an estimated surplus of ${formatCurrency(calculatedGap)} at age ${retAge}. Keep up this savings momentum.`;\n      } else {\n        // Capital Deficit\n        statusBadge.className = \"seg-tag ci-r\";\n        statusBadge.innerText = \"FUNDING DEFICIT SHORTFALL\";\n        \n        adequacyTag.className = \"nw-epf-tag no-epf\";\n        adequacyTag.innerText = \"ACTION REQUIRED - FUNDING GAP\";\n        \n        ratioFill.style.background = \"var(--orange)\";\n        gapValDiv.className = \"nw-val negative\";\n        \n        resultBanner.style.borderLeftColor = \"var(--red)\";\n        bannerTitle.innerText = \"Retirement Deficit Detected\";\n        bannerDesc.innerText = `You are facing an estimated shortfall of ${formatCurrency(Math.abs(calculatedGap))} at age ${retAge}. Explore our calculated actions below to help close this gap.`;\n      }\n\n      // Populate component breakdowns list\n      populateBreakdownTable(fv2, otherAssetsTotal, validatedFundNeeded);\n      // Generate actionable advice steps based on results\n      generateActionPlan(calculatedGap, nPre, validatedFundNeeded, yr1NeedsFV, rAdj);\n    }\n\n    function populateBreakdownTable(epfVal, otherVal, targetVal) {\n      const tbody = document.getElementById(\"analysis-table-body\");\n      tbody.innerHTML = \"\";\n\n      // List of resources\n      const rows = [\n        { name: \"Projected EPF Account Value ($FV_2$)\", val: epfVal, class: \"neutral\" },\n      ];\n\n      // Add custom funds\n      customFunds.forEach(fund => {\n        rows.push({ name: fund.name || \"Unnamed Resource\", val: fund.amount || 0, class: \"\" });\n      });\n\n      rows.push({ name: \"<strong>Total Estimated Capital Resources</strong>\", val: epfVal + otherVal, class: \"ss-b positive\" });\n      rows.push({ name: \"<strong>Retirement Target Capital Needed</strong>\", val: targetVal, class: \"ss-b negative\" });\n\n      rows.forEach(r => {\n        const tr = document.createElement(\"tr\");\n        tr.innerHTML = `\n          <td>${r.name}</td>\n          <td class=\"${r.class}\">${formatCurrency(r.val)}</td>\n        `;\n        tbody.appendChild(tr);\n      });\n\n      // Update comparison bars\n      const maxVal = Math.max(epfVal + otherVal, targetVal) || 1;\n      document.getElementById(\"bar-lbl-epf-val\").innerText = formatCurrency(epfVal);\n      document.getElementById(\"bar-lbl-other-val\").innerText = formatCurrency(otherVal);\n      document.getElementById(\"bar-lbl-total-req\").innerText = formatCurrency(targetVal);\n\n      document.getElementById(\"bar-fill-epf\").style.width = `${(epfVal / maxVal) * 100}%`;\n      document.getElementById(\"bar-fill-other\").style.width = `${(otherVal / maxVal) * 100}%`;\n    }\n\n    // Dynamic Action Plan logic based on financial gap calculations\n    function generateActionPlan(gap, yearsToRetire, fundNeeded, annualExpensesFV, realRate) {\n      const container = document.getElementById(\"action-plan-container\");\n      container.innerHTML = \"\";\n\n      let items = [];\n\n      if (gap >= 0) {\n        // Optimal scenario\n        items.push({\n          type: \"check\",\n          text: `<strong>Target Achieved:</strong> Your plan covers <strong>${(( (gap + fundNeeded) / fundNeeded) * 100).toFixed(0)}%</strong> of your target retirement capital pool. Review your asset allocation strategy as you draw nearer to retirement to lock in gains.`\n        });\n        items.push({\n          type: \"check\",\n          text: \"<strong>Preserve Purchase Power:</strong> Your nominal funds are growing faster than inflation. Consider moving a portion of funds into low-volatility fixed income to insulate against late-stage market shocks.\"\n        });\n      } else {\n        // Shortfall scenarios\n        const deficit = Math.abs(gap);\n        \n        // 1. Calculate extra annual savings required to bridge the gap (future value annuity factor)\n        let requiredExtraAnnual = 0;\n        if (realRate > 0 && yearsToRetire > 0) {\n          requiredExtraAnnual = deficit / ((Math.pow(1 + realRate, yearsToRetire) - 1) / realRate);\n        } else if (yearsToRetire > 0) {\n          requiredExtraAnnual = deficit / yearsToRetire;\n        }\n        const requiredExtraMonthly = requiredExtraAnnual / 12;\n\n        items.push({\n          type: \"alert\",\n          text: `<strong>Savings Adjustment:</strong> To bridge this gap strictly via cash additions, you must save an extra <strong>${formatCurrency(requiredExtraMonthly)} per month</strong> over the next ${yearsToRetire} years (earning your post-retirement adjusted interest rate).`\n        });\n\n        // 2. Recommend delaying retirement\n        items.push({\n          type: \"alert\",\n          text: `<strong>Extend Accumulation Phase:</strong> Delaying your retirement target age from ${document.getElementById(\"inp-retirement-age\").value} to 60 gives your investments longer to compound and reduces the post-retirement liquidation period.`\n        });\n\n        // 3. Voluntary EPF savings\n        items.push({\n          type: \"alert\",\n          text: \"<strong>Utilize EPF Voluntary Contributions:</strong> Employees can make voluntary top-ups directly to their EPF account up to RM 100,000 annually. Compounding this under EPF's historically high dividends is a low-risk method to narrow the gap.\"\n        });\n\n        // 4. Downsize lifestyle target\n        const optimizedReplacement = annualExpensesFV * 0.85; // suggest cutting expenses target by 15%\n        items.push({\n          type: \"alert\",\n          text: `<strong>Manage Lifestyle Expectation:</strong> Reducing your post-retirement income expectation by just 10% drastically drops the total capital hurdle required. Investigate if adjusting the income replacement target parameter from ${document.getElementById(\"inp-salary-pct\").value}% downwards aligns with downsized post-retirement expectations.`\n        });\n      }\n\n      items.forEach(item => {\n        const div = document.createElement(\"div\");\n        div.className = \"ap-item\";\n        div.innerHTML = `\n          <div class=\"ap-icon ${item.type === \"check\" ? \"check\" : \"alert\"}\">\n            ${item.type === \"check\" ? \"\u2713\" : \"!\"}\n          </div>\n          <div class=\"ap-text\">${item.text}</div>\n        `;\n        container.appendChild(div);\n      });\n    }\n\n    // Process button click in step 3\n    function calculateAndNavigateToAnalysis() {\n      triggerCalculations();\n      switchPage('analysis');\n    }\n\n    // Commentary Sync and LocalStorage auto-save\n    function saveAndCountCommentary() {\n      const text = document.getElementById(\"inp-commentary\").value;\n      document.getElementById(\"comm-char-cnt\").innerText = `${text.length} / 1000 characters`;\n      document.getElementById(\"lbl-commentary-print\").innerText = text;\n      localStorage.setItem(\"proretire_commentary\", text);\n    }\n\n    // Reset Form to initial state\n    function resetAllData() {\n      document.getElementById(\"inp-current-age\").value = 30;\n      document.getElementById(\"inp-retirement-age\").value = 55;\n      document.getElementById(\"inp-life-expectancy\").value = 80;\n      document.getElementById(\"inp-annual-salary\").value = \"60,000\";\n      document.getElementById(\"inp-annual-expenses\").value = \"36,000\";\n      document.getElementById(\"inp-salary-pct\").value = 70;\n      document.getElementById(\"inp-inflation-pre\").value = 3.0;\n      document.getElementById(\"inp-inflation-post\").value = 3.0;\n      document.getElementById(\"inp-return-retirement\").value = 5.5;\n      document.getElementById(\"sel-capitalization-method\").value = \"liquidation\";\n      \n      document.getElementById(\"inp-current-epf\").value = \"50,000\";\n      document.getElementById(\"inp-salary-increment\").value = 4.0;\n      document.getElementById(\"inp-epf-contribution-rate\").value = 24.0;\n      document.getElementById(\"inp-epf-growth-rate\").value = 5.5;\n\n      customFunds = [\n        { name: \"Unit Trust / Mutual Funds\", amount: 150000 },\n        { name: \"Private Retirement Scheme (PRS)\", amount: 45000 }\n      ];\n\n      document.getElementById(\"inp-commentary\").value = \"\";\n      localStorage.removeItem(\"proretire_commentary\");\n\n      renderCustomFunds();\n      togglePVPercentUI();\n      triggerCalculations();\n      switchPage('entry');\n    }\n\n    // Helper functions\n    function formatCurrency(val) {\n      if (!isFinite(val) || isNaN(val)) return \"RM 0.00\";\n      return \"RM \" + val.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });\n    }\n\n    function formatRawNumber(val) {\n      if (isNaN(val)) return \"0.00\";\n      return val.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 });\n    }\n\n    function escapeHtml(text) {\n      return text\n        .replace(/&/g, \"&amp;\")\n        .replace(/</g, \"&lt;\")\n        .replace(/>/g, \"&gt;\")\n        .replace(/\"/g, \"&quot;\")\n        .replace(/'/g, \"&#039;\");\n    }\n\n    // Triggers beautiful native formatting for print/saving to PDF\n    function triggerPrint() {\n      // Sync commentary to the print view div container\n      document.getElementById(\"lbl-commentary-print\").innerText = document.getElementById(\"inp-commentary\").value;\n      \n      const overlay = document.getElementById(\"pdf-overlay\");\n      overlay.classList.add(\"show\");\n      \n      // Allow CSS print layouts to resolve cleanly before browser dialogue\n      setTimeout(() => {\n        overlay.classList.remove(\"show\");\n        window.print();\n      }, 950);\n    }\n  </script>\n</body>\n</html>";

window.WQPlanningSuiteModules = window.WQPlanningSuiteModules || [];
window.WQPlanningSuiteModules.push({
  id: "retirement",
  title: "Retirement Planning",
  render(container) {
    container.innerHTML = '';
    const frame = document.createElement('iframe');
    frame.className = 'planning-suite-frame';
    frame.title = "Retirement Planning";
    frame.srcdoc = html;
    const resizeFrame = () => {
      try {
        const doc = frame.contentDocument || frame.contentWindow?.document;
        if (!doc) return;
        const h = Math.max(760, doc.documentElement.scrollHeight, doc.body?.scrollHeight || 0);
        frame.style.height = `${h + 32}px`;
      } catch (_) {}
    };
    frame.addEventListener('load', () => {
      resizeFrame();
      let runs = 0;
      const timer = setInterval(() => {
        resizeFrame();
        runs += 1;
        if (runs > 12) clearInterval(timer);
      }, 500);
    });
    container.appendChild(frame);
  }
});

})();

